package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.ModelRef;

/** Stable options captured when a Session is created. */
public record SessionOptions(ModelRef model, String workingDirectory) {
    public SessionOptions {
        if (model == null) throw new IllegalArgumentException("model must not be null");
        if (workingDirectory == null || workingDirectory.isBlank()) throw new IllegalArgumentException("workingDirectory must not be blank");
    }
}
